 enrich('c3s09',0,[['宋绮','外院病故通知的白素秋，床号乙三，押金收条四一；院方当夜的续收页仍写乙三、四一，只将来处改成“陆宅侧门”。两页经院方和外院分别出示，死亡日期早于续收登记。']]);
 enrich('c3s12',0,[['宋绮','钱庄付款回执在素秋病故通知之后开出，院方收款早于车行接人；两边备注都是“乙三、旧籍续用”。付款由冯经手，收款签在主管名下，原件各在原机构。']]);
 enrich('c3s15',2,[['宋绮','两份都是M2夹页所指保证书号。邵家当年收件副本写一名领粮户“已故，止领”；陆家底册对应栏改为“仍居北段，续领”。收件章、当年目录与独立保管相接；孔眼只支持重装，不能给改写者命名。']]);
 enrich('c4s04',1,[['何巡','码头值班原簿：许21:50到场处理故障，留到次日；两名值班员分别确认这段连续在场。夜间往返邵宅至少四十分钟，路程已由两处值班记录及安全复走核对。案发区间仍待查。']]);
 enrich('c4s11',0,[['宋绮','守夜人听见闷响约22:10；对街修钟人以刚校准的店钟回忆，只能限定在22:05至22:15，不能定秒。两份陈述独立登记。']]);
 enrich('c4s12',0,[['何巡','获准查验秦个人柜时，见证人在场，枪械擦拭布按原位置取出；书房缺弹与已封存涉枪物相互核对。枪柜有多人能用，擦拭布本身认不出开枪者，必须接上侧梯目击和不实作息。']]);
 enrich('c4s17',0,[['曹婶','原簿这行的入库号接上父亲异本目录；送件人为严鹤生，回执注明护运公所中转地址。对应行没有取回签收。今天核的是原簿，不是给摘录添一个新名字。']]);
 enrich('c5s03',0,[['何巡','窗台泥印朝外；落足区在檐下，同夜先前踩下的短工鞋痕仍在，却没有从窗台接下来的新落足。外露路段被雨损坏，只记缺损，不用来证明无人经过。']]);
 enrich('c5s09',0,[['宋绮','昨日约来的旧雇主今日核验：按登记的身体特征、随身旧物与客栈入住资料交叉确认死者戴魁。原核验另册保存；严的身份则用公所任务存根、连续任职与本人核对，不拿戴的票替严认人。']]);
 enrich('c5s11',0,[['宋绮','严交出的命令副件有当年的传递编号，公所收件簿可核；韩代理的付款记录，与执行者同号领款回执、撤守夜人名单相接。命令写的是搬账箱、撤守夜人，没有“杀人”二字。']]);
 enrich('c5s12',0,[['沈砚','八岁那年发大水，有人背我上岸。我只记得水声和自己攥紧的一片衣领，没看清那人的脸。那次转移，能和这些旧日期对上吗？']]);
 enrich('c5s12',1,[['宋绮','水患转移簿记着八岁沈砚的姓名与安置处，日期早于林照的拘押登记；火灾记录落在拘押尚未解除的那段。转移簿没写清背孩子上岸的人，先不要给他填姓名。']]);
 enrich('c6s02',0,[['宋绮','交接副件叫“转乙六”，只载韩的旧转移安排；正本由保护负责人保管，北仓原件更不在这张纸里。副件夹在黄灯室桌边，封角有订孔；你和当值役看过原状并登记。持件也必须经双人核验，温只有问诊预约。']]);
 enrich('c6s02',1,[['现场','你与当值役核好平面图：房门有内闩，高窗固定铁栅，门边递口只够信封通过；北面屏风后是洗手架，墙封实。黄灯室到公共廊下二十余步，外区小院经内门才到保护区。']]);
 enrich('c6s05',0,[['阿豆','这就是她从递口交给我的那张回单，背面写着“请何巡来，我受伤了”。我跑到值房交给何巡，原回单夹在收件簿里。折角是我跑时捏的，收件值役看见了。']]);
 enrich('c6s05',1,[['值班人','收件簿记约18:18收到阿豆交来的回单。我收好纸，回到廊口，才见温走到沈砚旁边，记的是18:20。敲门那阵重响记在18:24栏，我一直在廊口。三栏都照同一院钟，钟走得稍有误差。']]);
 enrich('c6s06',1,[['宋绮','我背身锁柜前，他说告辞。我没看见他走出门，也没看见谁举手。醒来时，我躺在柜边，后脑疼得厉害。纸递出去以后，我爬到门边，够着内闩推了上去，手指还被木刺扎了一下。'],['何巡','赵成离室后到另一值房核账，两名值班人各自说明其连续在场；杂役送工具的交接也登记了。未经登记的进入不能凭一张预约单彻底排除，所以还要查失物。']]);
 enrich('c6s06',0,[['宋绮','门外有人喊我的名字，我听出是何巡。想站起来时眼前发黑，只抓到洗手架的边沿；架子朝我倒过来，我摔到膝盖，喊了一声。']]);
 enrich('c6s09',1,[['沈砚','先把这一项问清：你离开黄灯室时，拿过桌边的“转乙六”副件吗？'],['温既白','没有。那份副件我没拿过。我只带走自己的药袋。']]);
 enrich('c6s08',0,[['宋绮','逐件清点：五案副本都在；少的是事前登记的“转乙六”。其他人不能拿一段路线接走韩，正本仍在负责人处。我的桌边留下的封角由何巡当场包存，编号与现场位置都在封条上。']]);
 enrich('c6s11',0,[['接收员','温在外侧接收窗口亲手递来“转乙六”，说按这份把韩交给他。同班另一人全程在旁。编号已作废，我们拒绝交人，将递交人、原件现状和时刻当场登记。']]);
 enrich('c6s12',0,[['何巡','两名当班人将扣留副件直接交我，交接未离见证。订孔、编号和撕裂边与宋桌边封角相合，能确认是失窃那一份，不是只同号的抄件。温此前否认拿件，尚未交代怎样取得；纸纤维不能告诉我们谁打了第一击。']]);
 enrich('c6s13',2,[['后勤员','他在外院拦住我，打伤我，抢走能开内门的后勤钥匙。我看见他拿钥匙进去，守卫到时我还倒在这里。'],['独立守卫','我们入内时看见温正在拉缚住韩的绳，钥匙在他手边；韩被绑在椅上。先前谁伤宋，我没在场，这次控制和夺钥匙的现场我会独立签录。']]);
 // Case 1: clothes and identity, an invitation that is not attendance, then custody.
 add('c1s07',2,'timeline','missing-man','这张寻人表的最后确定时点该填在哪里？',[c('c1s06',1,'昨夜问灯时的衣物说明'),r('c1s07',2,0,'梁福不知道换藏时刻')],['只填到访时人已不在；衣服送达另列，继续找最后见过宋旺的人','到访能确定缺席，送衣只能确定衣物先已交付。'],['填问灯以前已离开；衣服也是那时送的','送衣时刻不等于离开时刻，梁福明确不知他何时换地方。'],['填刚听见犬声时离开；声音说明人就在附近','犬声没有辨认出人，不能把声响变成宋旺的行程。'],'宋旺具体离开时刻留空，衣物交付不替人物行程计时。','你们沿已标边路回顾宅，寻人改查最后接触者；顾承安没有被派去追远处的影子。');
 add('c1s09',1,'custody','letter-custody','残信与寄送簿能接起哪一段，下一段还缺什么？',[c('c1s08',1,'梁福说明拾得与留存'),r('c1s09',1,0,'柳月生亲自提供底簿'),r('c1s09',1,1,'两件记录的可查范围')],['能核写信和寄送；是否赴约另找行程见证','两条独立保管来路使寄送可查；簿册没有登记到场。'],['能核柳已赴约；没有到场不会留下寄送记录','寄送发生在会面之前，寄信不能保证后来赴约。'],['梁福隐瞒过弟弟，因此残信与底簿都应作废','隐瞒需要询问，但不消除两件实物各自可核的来源。'],'残信来自梁福留存，底簿由柳交验；寄信与未赴约可以同时成立。','柳只同意复制与约见相关的一条。其余客人私信留在柜内，陶后来的口信被单独列为待核行程。');
 add('c1s12',2,'flow','clothes-not-body','更正误传死讯时，哪条衣物链必须与身份栏分开？',[c('c1s06',0,'宋嫂说明旧衣经手'),r('c1s12',1,0,'梁福的亲手交付'),r('c1s12',2,0,'宋嫂辨认死者')],['顾承安→梁家→宋旺是衣物链；宋嫂的辨认另用于死者身份','同一件衣服流转过，不能一直替最初主人报姓名。'],['认出顾承安衣服，就把死者仍记作顾承安','这忽略了两次交付和熟人对实际死者的辨认。'],['改成宋旺后删掉衣物链，免得再认错','身份更正并未解释追赶为何跟着旧衣，流转仍是需要保存的线索。'],'死者登记宋旺，顾承安仍活着；衣物流转完整保留。','何巡更正对外死讯。宋嫂可以按弟弟的名字办理告别，旧衣另包封存，继续追查追赶为何找错人。');
 add('c1s13',1,'hypothesis','motive-and-action','搜查申请中，哪些材料支持查养药屋，画像应放在哪里？',[r('c1s13',0,-1,'旁支与契约的条件'),r('c1s13',1,-2,'遇害前运犬与供肉'),r('c1s13',1,-1,'小栓识别交鞋门')],['列继受条件、运犬供肉与交鞋地点；画像只作查访起点','动机和实际筹备来自不同材料，能支持继续搜查；相貌不承担定罪。'],['列画像相像为杀人证明，其余只作旁证','相似外貌不能证明养犬、取鞋或当夜追赶。'],['陶是旁支且家中养犬，已经足以认定每次死亡','动机和养犬不能直接认定每次实施，仍要查现场物件和行动。'],'搜查方向落在有来路的犬、鞋与养药屋，不以画像认凶。','何巡按上述事实申请查验，顾承安留在保护处；江蘅提供的路线仅用于她亲历的区域。');
 add('c1s16',2,'flow','hound-action-chain','提交本案时，怎样连接取鞋、错认死者与今夜放犬，同时保留空白？',[r('c1s16',0,-1,'犬舍旧鞋清点'),r('c1s16',1,0,'旧衣转交链'),r('c1s15',2,-1,'今夜放闸目击'),r('c1s04',1,1,'初案现场的限制')],['分别提交取鞋养犬、衣物流转和今夜放犬；旧堤死因不冒充目击','多段行动相互支持陶的追杀安排，但今夜目击不能倒填最早的致死细节。'],['今夜见陶放犬，等于每次致死过程都有人亲见','目击有当晚范围，顾守礼遇害时的雨损和检验空白仍在。'],['精确死因不明，就不能提交已经独立核实的追杀安排','局部未知不使取鞋、养犬、放犬和交付记录全部失效。'],'陶的追杀安排有物证与行动支持，宋旺身份更正；顾守礼精确生理死因依现有检验处理。','本案行动链分段交何巡。江蘅的拒绝引诱、寄警告与保护请求独立保留，不必先原谅陶才能离开。');
 add('c1s18',2,'crosscase','m1-handoff','带什么去钱家，才能使下一案真正接续这次查验？',[r('c1s17',1,0,'原册抵押编号'),r('c1s17',2,0,'两见证核副本'),r('c1s18',2,0,'钱家核对预约')],['带已核编号、日期和认证副本，原件留顾家；向钱家查同号凭据','编号给出可追索对象，独立保管让原件不随同行选择消失。'],['把顾家唯一原件交温，靠他认出所有旧案参与者','温的熟悉不替代原件来源与钱家独立核验，也无权自动持原件。'],['抵押清册已指钱家，直接将钱家列为纵火实施者','抵押证明利益与凭据联系，未证明火灾指使或实施。'],'M1只将调查接到钱家的对应凭据，抵押本身不是纵火罪证。','管理人留下查阅位置和两名见证的签押。你们按预约出发，温帮谁拿行囊都不改变原件仍在顾家的事实。');
 // Case 2: overlapping actions, limited sight, a tested financial route.
 add('c2s02',2,'timeline','banquet-map','宴后第一张接触表，应如何安排这些不同记录？',[r('c2s02',0,0,'灯座、灯心与新漆登记'),r('c2s02',0,1,'小梅搬物路径'),r('c2s02',2,1,'进出时间要求')],['把接触新漆者和接触灯心者分列，再核各人进出','门框接触面更大，尚不能把所有沾漆衣物都算成取灯。'],['将新漆附近出现的人全部记为接触灯心','两处不同位置没有自动对应，搬物也会经过门框。'],['只记最后离开的守灯人，前面来客不再查','离开次序不是失物发生时点，其他在场者仍须列入。'],'宴前物样和进出记录分开保存，为失物后的路线核验留下基线。','小梅刚搬过东西的路也登记了。明日有人再指向她的衣箱时，你能查实际接触，不能只听谁先指人。');
 add('c2s04',2,'flow','paint-clothes','这件藏起的外衣，把调查带到了哪一段？',[r('c2s04',1,0,'漆痕的位置和限度'),r('c2s04',2,0,'小梅说衣服来自交洗'),r('c2s04',2,1,'分别追问收与藏')],['先核谢的外衣何时交洗、何时被藏；漆痕只说明经过门框','衣物归属、接触地点和藏衣各是一段，需按经手顺序查。'],['小梅藏着沾漆衣服，灯心必由她拿去卖了','材料没有给出小梅取灯、交付或收款，不能越过缺失环节。'],['衣服属于谢，小梅的藏衣行为可以不记','持有人与藏衣者可不同，隐瞒仍是需要保留的实际动作。'],'外衣归属与藏衣行为分别查，漆痕不证明后续盗卖。','衣箱在小梅面前逐件登记；何巡另问交洗经手人，没有以紧张为由将她当众带走。');
 add('c2s08',1,'testimony','mei-correction','小梅醒后的说明，应怎样更正“藏衣就是见过偷灯”的旧猜测？',[r('c2s08',0,1,'小梅亲口说未见带灯'),r('c2s08',1,0,'交洗、发现、藏衣'),c('c2s07',0,'意外与取账的实际后果')],['保留发现漆痕和藏衣；她猜谢取灯，未目击带灯出去','亲口说明修正猜测来源，不撤销她实际藏衣的行为。'],['她肯替谢藏衣，就采信她推测的全部路线','维护一人不增加视线，也不能补后廊交付。'],['说明信已解释一切，不必听她本人','她仍活着且愿意说明，信不能替她决定事故原因和之后去处。'],'小梅亲历的是交洗与藏衣，盗卖是她当时的推测。','问话按她休息分次进行，谢同意继续查自己的路线；小梅不需要用恋爱承诺换取工钱或治疗。');
 add('c2s09',1,'testimony','half-a-witness','映棠的站位复核后，哪两句可以同时留在卷里？',[o('c2s09',1,'她看见取灯'),o('c2s09',3,'她看不见后廊'),r('c2s09',0,0,'实际遮挡记录')],['她看见谢取物；后廊是否交人，她没有看见','真实目击与明确视线空白并不冲突。'],['后廊看不见，所以她看见取物也不可靠，应全删','后段遮挡不推翻前段在视线内的动作。'],['她看见谢取物，就能证明谢一直持有到抵押行','从拿起到最后处置之间仍缺交接环节。'],'取物目击保留，离开后视线遮挡处标为未知。','映棠在图上签认自己能看见的范围。下一步查后廊经手人，谢不能要求她为了证明自己无辜而撤回目击。');
 add('c2s10',1,'hypothesis','drug-limit','给药记录补齐后，哪一项结论现在能成立？',[o('c2s10',1,'药包和交接记录'),r('c2s10',0,1,'行为与影响的区别'),r('c2s10',1,0,'周济承认未充分说明')],['未经充分说明的给药成立；药物影响范围与失物交付仍要另查','给药并不生成一段完整行动录像，也不能解释所有记忆空白。'],['既用过药，就认定谢当夜一切动作都无意识且免责','现有材料未证明药物对每段行为的具体影响，更未证明盗卖人。'],['再给谢同样药物重演，就能补上没人见的路线','重演有风险，且今日重演不能变成当夜的独立目击。'],'保留给药行为的责任，不以危险重演填补证据。','药包与记录分别封存；后廊复走只核原有站位，不再服药，周济的职业身份也不能免除这项查问。');
 add('c2s11',1,'flow','handoff-gap','后廊这份新证言，补上哪一格，又留下哪一格？',[o('c2s11',2,'店伙看见接包'),r('c2s11',1,0,'只听代存请求未见包内'),r('c2s09',0,0,'映棠的视线边界')],['补谢交包、惟善接包与代存原话；包内及后来处置需接收当物','这与映棠只见取物相容，但店伙不能替包里物件作证。'],['店伙看见包，就足以确认包里是灯心且惟善已盗卖','包内未见，盗卖也还没有收当与付款支持。'],['映棠没看见接包，所以店伙证言与她矛盾','遮挡处发生新动作，正是两段目击可以接续的位置。'],'代存请求有独立见证，物件内容与后段去向继续查验。','宋绮把后廊节点接到站位图，给收当处发的是物样核验请求，而非一份已写好凶手姓名的口供。');
 add('c2s12',0,'timeline','shortfall-before-loss','基金短款与失灯，哪一个先发生，这能解释什么？',[o('c2s12',0,'已取得的基金账'),o('c2s12',1,'亏空早于宴夜'),r('c2s12',0,1,'动机与动作限制')],['亏空先于失灯；交账压力可解释催促，仍须查抵押与收款','先后限制了“失灯才造成亏空”的解释，却不自动证明抵押者。'],['失灯造成基金亏空，先找到灯就能结清善堂账','原账的亏空落在宴前，顺序相反。'],['既有亏空动机，就不用去收当处核实物','动机不完成失物流转，关键后段仍在独立机构。'],'善堂先有短款，失灯后处置仍需实物和付款链认定。','映棠不再被催着以婚约填补善堂困局；经许可的副本留下来源，下一步去收当处核物和款。');
 add('c2s13',1,'flow','pawn-payment','化名这一栏被拆开后，哪条关系已经得到两个机构支持？',[r('c2s13',1,-2,'收当物样、代办与款项'),r('c2s13',1,-1,'原单和钱庄回执分处取验'),r('c2s11',1,0,'先前代存原话')],['代办交物、惟善安排款入善堂；回接他先前接包，继续核代存权','代办姓名不等于实际委托人与收款人；物样、款号与接包可以逐段连接。'],['先接成谢委托代办、善堂代谢收款；惟善只见过后廊的包','代办本人说明由惟善委托，付款去向又由惟善指示；当前材料没有谢委托代办的那一段。'],['先接成代办自行拿物抵押，惟善仅是被填写的收款人','此说漏掉代办对委托的独立陈述和惟善安排付款去处，不能只看化名栏而略过另外两栏。'],'收当、代办与款项支持惟善控制后段处置；其处置权限还须核对代存请求。','经办人得到独立护送，原单留收当处、回执留钱庄；灯心暂存地点通知双方，避免再次失去可查去向。');
 add('c2s15',2,'flow','three-acts','结案时该怎样写这三段，而不让任何一个人的错误替另一个人免责？',[r('c2s09',1,0,'映棠确认拿取'),r('c2s11',1,0,'代存请求'),r('c2s13',1,-2,'抵押与款项核对'),r('c2s15',0,0,'三段材料汇拢')],['谢拿取并交存，惟善接存后私押；小梅藏衣、周济给药另记','三段有不同的行为人和权限，不能统成一名全责者。'],['谢先碰过灯，所以后续抵押只算谢一人的事','惟善受托代存后另行处置，有独立行动和款项证据。'],['追回灯心就撤下盗卖和隐瞒，让关系恢复即可','物件追回不取消已经发生的处分、藏衣和给药。'],'取物、代存、私押分别认定，相关隐瞒和给药不相互抵销。','小梅领取应得工钱后按自己计划离宅；映棠与谢另谈关系，归还灯也不能封掉惟善的基金账。');
 add('c2s18',0,'crosscase','m2-handoff','钱家存根带来下一站，哪一项应跟着M2进入陆家的查询？',[r('c2s17',0,0,'M1与旧存根对应'),r('c2s17',1,0,'陆家保证编号'),r('c2s17',2,0,'原件和副本保管')],['查旧抵押夹页的陆家保证书号与出具手续，基金盗卖另册','同一家两笔不同时代的抵押不能合成一件事。'],['把新近灯心抵押当作十八年前北仓盗粮的直接证明','年代和对象不同，新案只证明本案流转。'],['钱承认见过林照材料，就采信他对火灾不知情的全部解释','承认和否认都需核验，下一处保证书正用于补独立来源。'],'M2由同号旧抵押存根接到陆家保证书，不把新基金移入十八年前。','认证副本按编号装入另一册；铜莲灯的共同保管仍由映棠与守灯人协商，不以停止旧案查询交换还灯。');
 // Case 3: a living person and a dead person each retain their own name.
 add('c3s03',0,'decision','consent-before-disappearance','明日接人安排应以哪份授权为准？',[o('c3s03',1,'照宁提出离居与拒签'),r('c3s03',0,0,'两个独立请求'),r('c3s03',0,1,'本人保留股份')],['按她确认的离居约定接人，股份仍由她本人决定','离家不是放弃财产，也不是别人替她改主意的许可。'],['她要离家，便替她签下股份放弃，方便尽快走','她明确说未放弃财产，不能用保护替她处分。'],['等丈夫确认后再写约定，避免与家里意见不同','本人已有明确意愿，丈夫的反对不能代替她作答。'],'离居与财产分别授权，任何变更须再次问本人。','秋岚保留见面时刻与地点，何巡可依这个外部约定查失约；照宁不必先交出股份才有可去的地方。');
 add('c3s05',2,'timeline','false-death-time','三张记录里，哪一对先迫使你暂停下葬，同时继续寻人？',[r('c3s05',2,-1,'死亡单、午后货单、出车册'),r('c3s05',1,0,'送货人亲见范围'),c('c3s04',0,'两页独立案件记录')],['清晨死亡与午后本人签货、说话冲突；暂停假死亡处置，查车行','至少一个身份或死亡记载有误，但棺中是谁、本人在哪仍分别核。'],['同日有出车册，便直接认定车上是素秋遗体','册上接人不自动提供身份，需核出发地、接收与本人。'],['午后还活着，便宣告当天无人死亡，素秋记录也删去','照宁与素秋是两个人，照宁的活人证据不能抹去素秋病故记录。'],'照宁死亡记载与独立午后记录冲突，停止仓促下葬，沿车辆寻人。','下葬和股份清算被暂停。秋岚留下签货见证，查棺中身份与寻找照宁同时进行，没人需等陆家再给一句解释。');
 add('c3s06',2,'custody','body-custody','给棺中人恢复名字，需要哪条连续链，而非只认衣服？',[o('c3s06',1,'姨母否认领尸委托'),r('c3s06',0,0,'两处独立交接'),r('c3s06',2,0,'连续护理记录'),r('c3s06',1,0,'姨母辨认的范围')],['护理记录→停灵所领出→陆宅接收，再合遗物与熟人核验','多种来源连续支持素秋身份，也把冒用委托单独暴露。'],['旧衣熟悉即可，无需再核车和领尸手续','衣服可转交，单项辨認不足以说明遗体从何处来。'],['姨母没委托，所以遗体从未离开停灵所','未授权不等于未发生，两处交接正要查清谁冒领。'],'棺中为素秋由连续护理、交接及辨认共同支持；冒领另查。','何巡按本名通知素秋家属，冒用委托不能写成姨母同意；照宁的寻人页仍保持开放。');
 add('c3s09',0,'hypothesis','bed-and-deposit','“只是同名”能够解释院账的哪一处组合吗？',[r('c3s09',0,-1,'乙三床与四一押金的续用'),r('c3s09',0,0,'床号押金搜索对象'),o('c3s09',3,'先找具体床位')],['不能解释病故后同床同押金、来处改陆宅；立即查乙三本人','组合给出可以安全查找的床位，尚需本人和接送核身份。'],['同名可能存在，便等院方有空再全面查账','同一旧籍和押金连续使用尚未解释，拖延可能再次转院。'],['旧床号重复，就直接在案卷写照宁已在乙三','强线索确定搜索对象，认人仍须实际见到与交叉核验。'],'暂停乙三再次转院，先核床上本人；旧册预约可以延后。','温放下到点才能取出的旧册，何巡安排保护查验。床位成为实际救援目标，纸上姓名不能再拖住寻找活人。');
 add('c3s10',2,'hypothesis','living-identity','布条写出秘密账误之后，哪一套核验可以恢复本人身份？',[o('c3s10',1,'照宁布条'),r('c3s10',0,1,'宋绮查旧账来源'),r('c3s10',2,0,'多项身份链'),r('c3s09',1,0,'车夫只能认接送地')],['本人陈述、熟人核验、原账错误与接送记录合看，秘密问题只作一环','每项都有范围，结合后才支持本人身份，不能依一句暗号。'],['知道未公开账误就足以确定身份，其他人不用再问','可能经手账目的并不只有一人，秘密知识不是万能认证。'],['院账写素秋，就要求她先承认素秋身份才能离院','院账本身正被调查，不能让被质疑记录否定眼前人。'],'照宁身份由相互独立来源确认，院方旧籍不再替她作答。','女医将她交独立保护，秋岚按她愿望准备染坊住处。出院不附带回丈夫家的条件。');
 add('c3s12',1,'timeline','planned-transfer','“误信家属、临时送医”的说法，在哪一处受到实际记录反驳？',[r('c3s12',0,-1,'病故后、接人前的付款'),r('c3s12',1,0,'车夫听见拒绝去院'),r('c3s10',1,0,'照宁本人拒绝再次转院')],['病故后接人前已付旧籍续用款，且当事人要求去染坊；查预先准备','付款时点和本人意愿使单纯误送解释不足，仍分别核各人知情。'],['只看主管后来交的便条，就把所有人最初共谋都认定','便条仍需核验，不能替每个参与者确定最初知情时间。'],['丈夫同意送医就等于本人同意，付款无需再问','本人拒绝与去处明确，丈夫的说法不能取消实际强制。'],'身份替换存在事前准备，付款、接送与更名逐段查参与人。','冯的“受托送医”和主管便条分开入卷，照宁的拒绝按原话保留，院方不能再用旧籍安排新转院。');
 add('c3s13',1,'testimony','father-son-scope','陆存礼得知疑点后催清算，该怎样与最初绑送分开？',[r('c3s13',1,0,'何巡限定知情日期'),o('c3s13',1,'照宁拒绝以撤诉换财产'),r('c3s08',0,0,'股份由本人处置')],['查他得知疑点后仍催清算的行为；最初调包另核，不以还产换撤诉','后续明知行为可独立追究，不能倒推他参与了每项前置动作。'],['他是父亲，最初接送与替名都并入他名下','亲属身份不提供在场、指令或付款证据。'],['肯还股份就把后来催办删掉，免得妨碍和解','归还本应属照宁的财产不是购买撤诉的条件，也不改变已发生动作。'],'父子责任按各自行为与知情时点分列。','照宁的两份请求分别受理：停止清算和继续追究。陆家不能凭还产承诺换来她回家或撤回陈述。');
 add('c3s15',2,'crosscase','m3-versions','旧孔眼与同号异本并置后，真正能够提交的差异是什么？',[r('c3s15',0,0,'装订痕可知范围'),r('c3s15',1,0,'独立收件副本来源'),r('c3s15',2,-1,'同号两版领粮户状态')],['同号材料把“已故止领”变成“仍居续领”；内容差异成立，改写者另查','独立保存的对应内容使纸面差异可复核；孔眼本身不认作者。'],['修书手艺看出重装，即可指认陆亲手写了每个字','重装的经手和内容作者不同，单凭孔位不能认人。'],['陆说只是修补，两版内容虽不同也不再调查','修补能解释外观，不能解释同号记录在领粮资格上的改变。'],'M3证明同号保证书版本不同，作者与命令仍需付款和投递补证。','两处原件各留原处，宋绮制作逐行差异表。下一步按誊录与投递来源查人，不将一排针孔写作口供。');
 add('c3s16',1,'testimony','father-involvement','父亲署名出现后，眼前哪一种记录既不隐去参与，也不扩大参与？',[o('c3s16',1,'陆承认安排重誊'),r('c3s16',0,0,'旧工资与收件信息'),r('c3s16',0,1,'付款证据的限度')],['记录沈怀舟参与誊录的材料，威胁、明知程度与后果待独立核查','笔迹只能辅助，工资与收件支持的参与范围应照实保留。'],['认得父亲笔迹就认定他策划全案','字迹和工作付费没有给出策划、命令或全部知情范围。'],['父亲已故无法答辩，就将署名从差异表中隐去','无法立即答辩不取消材料，应保留范围与待核项，而非删去事实。'],'父亲是可查的经手者，熟悉笔迹不替代来源也不定全责。','沈砚同意歇一会儿，却没有藏起签名。下一站查父亲实际收到、交出过哪份材料。');
 add('c3s18',2,'crosscase','m3-next-address','邵家回函到了，下一步怎样既追上送件人，又不把摘录当原簿？',[o('c3s18',1,'送达目录摘录'),r('c3s18',0,0,'M3范围'),r('c3s18',1,0,'何巡当日发查询'),r('c3s18',2,1,'照宁后续授权')],['先发身份关联查询，办完照宁保护；预约邵家查原投递簿','查询可以与收尾并行，摘录给方向但不代替原件核验。'],['摘录写严，就把严知道的全案内容写进结论','名字和地址是查访索引，不是尚未听到的证言。'],['立即连夜走，不用完成照宁已提出的后续保护','跨案线索不会替代本案受害者已授权的具体安排。'],'M3携差异表与来源接续原簿查询，查询发出时间清楚保留。','照宁的保护与委托手续办妥后明早出发，何巡的查询已在路上；以后收到回音不会被写成当日跨城神速查清。');
 // Case 4: communication control and two independently supported deaths.
 add('c4s02',2,'hypothesis','key-is-not-only-route','钥匙交接已经登记，书房排查还必须保留哪条路径？',[r('c4s02',0,0,'钥匙真实交接'),r('c4s02',1,0,'事前已公开的侧梯'),r('c4s02',2,0,'发现之后的接触')],['保留侧梯入内廊，区分发现前后；钥匙不再证明唯一入口','公开侧梯使“唯钥匙持有人能进”失效，机会需按时段重查。'],['只查拿备用钥匙的云筝，其他通路排除','侧梯是已知通路，不能因钥匙显眼而忽略。'],['所有清晨进书房者都算昨夜进过','发现后的接触不能倒填案发前行程。'],'入口与时段分开，备用钥匙不是唯一的机会证据。','侧梯从第一张公开图开始保留，何巡分别查夜间和发现后进出；云筝不再因一把钥匙独自承受围问。');
 add('c4s03',2,'testimony','same-lie','姐妹都否认来客，门房记录却有许；现在能把哪件事写实？',[o('c4s03',1,'云筝替姐姐抢答'),o('c4s03',2,'姐姐反对代答'),r('c4s03',2,0,'门房见来客')],['来客被隐瞒成立；姐妹各自原因与昨夜行动继续分开核','相同否认并不证明共同杀人，也不说明二人知道相同内情。'],['同一句谎说明合谋，二人时段不必再查','合谋需要实际动作与共同意图支持，不由一句相同否认推出。'],['既为保护隐私，就把门房的独立见证删去','隐私可以限定公开范围，相关来访事实仍须保存。'],'隐瞒来客与秘密关系待核，杀人另查机会和动作。','姐妹分开等候，云岚的信只核案情相关部分；许的来访进入实际查询，不当众宣读私人情话。');
 add('c4s05',0,'hypothesis','will-status','这份改立预约，应当怎样影响遗产动机判断？',[o('c4s05',1,'秦的指控'),o('c4s05',2,'云岚知情范围'),r('c4s05',0,0,'外聘见证人确认未签')],['标为预约讨论、尚未生效；谁知道预约再查，不认定云岚已失产','威胁、预约与正式生效是三个状态，不应混写。'],['有草稿就视作新遗嘱已生效，从而确定杀人收益','外聘见证人明确未签，不能把未完成程序作既成结果。'],['秦知道准确预约日，因此肯定偷听过案发密谈','他经办预约存在正常知识来源，还需查具体动作。'],'改立未完成，财产动机与谁掌握预约分开查。','未签草稿封存，何巡询问经办名单；云岚只回答亲知事项，不被要求解释她本不知的预约日期。');
 add('c4s06',1,'custody','missing-worker','失踪女佣的箱子被多人翻过，该怎样处理“携款逃走”的说法？',[r('c4s06',0,0,'无事前清单的短少'),r('c4s06',1,0,'寄书安排可独立核验'),o('c4s06',1,'曹婶保存收条')],['把短少列未证实，保留寄书收条并按最后行程寻人','没有基线就不能证明谁带走什么，寄书是可核的本人安排。'],['箱子里少了东西，就把她写为携款离开','后来没看见不等于她主动带走，箱子已经受多人干扰。'],['她准备寄书，就能证明她从未离宅','未来计划不证明实际行程，只能帮助查找和修正动机猜测。'],'公开寻何素禾，私逃未成立，书包与收条按原状保留。','渡口与车行收到姓名和最后去向的查询，素禾的书没有被当作遗弃物扔掉，曹婶也得到保护联系。');
 add('c4s09',1,'testimony','letters-command','签收单与曹婶说明，能把秦的“伯父命令”核实到哪一步？',[o('c4s09',0,'外部签收单与秦署名'),o('c4s09',1,'秦称受伯父命令'),r('c4s09',1,0,'曹婶没听见不等于从未下令')],['秦接过对应信有外部支持；伯父是否命令扣下全部信仍未知','签收证明经手，曹婶证言没有覆盖全部命令。'],['曹婶没听见命令，就确定秦这句每个字都是谎言','未听见不等于证明从未发生，仍要找独立材料。'],['伯父反对婚事就足以证实他命令扣下每封信','一般态度与具体截信指令不同，不能混作一份授权。'],'通信经手可查，秦关于命令的解释继续核，不自动推出命案。','云岚依据外部日期列出未收到信件，封库改由新保管人控制；秦不能再以最熟悉家事为由替她挑选材料。');
 add('c4s11',2,'timeline','night-window','约22:05—22:15的案发区间，与两人的行程应怎样比较？',[r('c4s11',0,-1,'声音只能限定区间'),r('c4s04',1,-1,'许在码头连续在场及往返'),r('c4s11',2,0,'秦约22:15下侧梯')],['许的码头见证与路程排除该段往返；秦22点睡下与侧梯目击冲突','不是靠丈夫身份免责；秦有机会矛盾，还要接现场证据。'],['许21:50到码头，四十分钟够在22:15以前往返一次，继续保留该路线','从21:50起四十分钟已到22:30，晚于区间上限；两名值班员还另有连续在场见证。'],['秦约22:15才下楼，已经晚于约22:10的闷响，可以排除书房机会','22:15下侧梯不能证明此前不在楼上，且与22点已睡的说法冲突；仍要接书房材料，不能只凭一声响定人。'],'许在该区间往返不成立，秦的作息需据侧梯目击与现场复核。','何巡把许的机会排查结果写明，另对秦实施控制并申请查验；闷响仍叫闷响，守夜人没有被改成亲眼见枪击。');
 add('c4s12',2,'flow','two-victims','两名死者各需要哪一条行动链，才能避免用一个嫌疑结两案？',[r('c4s12',0,-1,'书房枪械材料及其局限'),r('c4s11',2,0,'侧梯目击'),r('c4s12',1,0,'车夫、泵房邻人和办事点'),r('c4s12',2,0,'个人柜物件清点')],['书房接侧梯、作息与涉枪物；素禾接车行、假办事点、泵房与取走物','两条独立支持链分别提交，单件局限和秦的解释都保留。'],['既然截信成立，就能直接认定两次谋杀','截信说明通信控制，不提供两处致死的全部行动证据。'],['只提交主人书房证据，素禾作为同一凶手附带结案','素禾是独立受害者，泵房链有自己的来源和被带走过程。'],'两条行动链分列，擦拭布、工资外封都不独自包办定罪。','素禾的名字与书房死者各占一份材料清单；曹婶继续受保护，没人需要再受一次伤来补证。');
 add('c4s15',2,'custody','old-letter-custody','十八年的寄存信，为什么现在可以作为可追查材料，而非袖中秘信？',[r('c4s15',0,0,'当年编号与历次清点'),r('c4s15',1,0,'父亲自述'),r('c4s15',2,0,'曹婶的有限见证')],['目录、历次清点与交付见证接起保管；信中威胁解释另找旁证','保管连续支持来源，不使写信人自述的每句话自动真实。'],['曹婶认识父亲，就无须核目录和历次交接','熟悉不能替代十八年的保存出处。'],['找到了亲笔解释，就把威胁与全部无辜一并确证','信自述明知不实仍签收，威胁部分没有独立见证完整支持。'],'寄存来源可回查，父亲自述与异本分别核，威胁保留为待证解释。','原信从指定库位取出后再封存，沈砚带走认证副本；他能感谢父亲留下纸，也不能借此删掉父亲签收的不实材料。');
 add('c4s16',2,'crosscase','father-both-sides','温建议将父亲那页先放附卷，你交出的清单该如何处理？',[r('c4s16',0,1,'责任与补救'),r('c4s16',1,0,'曹婶见证边界'),o('c4s16',1,'温建议暂放附卷')],['异本补救和明知签收同时列主清单，威胁仍列待核','事实范围不会因亲缘或同情改变，补救也不抵销参与。'],['只交异本，等韩认罪再考虑父亲签收','这会使当下清单刻意缺页，后续无法完整复核责任。'],['为了公平，把父亲推定为和韩完全同责','公平不是抹平角色差异，父亲的经手不等于策划和指使。'],'父亲责任与补救都不删，证言只到亲历范围。','沈砚在主清单上留出父亲单独一页，温停下收纸的手。这份拒绝后来仍在六案桌上，不能被改成从未发生的分歧。');
 add('c4s18',1,'crosscase','m4-handoff','M4该怎样把你们带到周宅，而不靠同一天突然查明改名史？',[r('c4s17',0,-1,'原簿与当年交付'),o('c3s18',1,'T29先得摘录'),r('c3s18',1,0,'T29发出查询'),o('c4s17',2,'公所关联回覆')],['记录T29发询、今日核原簿和收到关联回覆，携副本去与本人再核','三步取得时间不同，关联记录是方向，仍需要本人和别处档案确认。'],['见到周泊川名字就改写成严已亲口承认全部旧事','尚未见本人，回覆不能变成未取得的口述。'],['把寄存原件带去让周独自辨认，省掉多方来源','认证副本足以查询，独立保管避免原件被单一证人控制。'],'M4由异本、投递回执和有限证言接续周宅，非万能真相信。','秦案与北仓材料分册归档。原信仍在邵行，沈砚按已获得的会面回函前往，途中仍需核新的命案消息。');
 // Case 5: a staged corpse, a real attack, and bounded history.
 add('c5s02',2,'hypothesis','name-on-clothes','棺中人的临时身份该怎样写，才不重犯旧衣误认？',[r('c5s02',0,1,'仆人只认衣服'),r('c5s02',1,0,'妻子说明婚戒习惯'),c('c1s12',0,'第一案曾将衣服与人分开')],['先记身份待核；衣物归周、戒指缺失各列，继续独立辨认','过去亲历过衣物误认，此处仍须新证据，不能机械照搬结论。'],['没有婚戒便认定周一定活着，马上撤下死亡调查','习惯产生疑点，不能单独证明生还或替死者认人。'],['衣服和身份牌都属于周，就直接请家属领尸','物件可转移，面容又不能可靠辨认，必须查其他身份依据。'],'遗体身份待核，已核物品归属先行登记。','棺盖暂停合上，余雪梅不再被催着点头；你把第一案旧衣教训用于提问，而没有把眼前人先写成另一个宋旺。');
 add('c5s03',2,'hypothesis','rain-comparison','“雨把脚印都冲没了”必须解释哪一个反例？',[r('c5s03',0,-1,'檐下仍有旧痕但无落足'),r('c5s03',1,1,'安全测量范围'),r('c5s03',2,0,'路径缺口')],['檐下可比较旧痕仍在，窗下缺连续落足；削弱逃窗，留谁造痕待查','只用受遮蔽的比较区，外露雨损不被冒充完整反证。'],['外面没有新印，就断言案发当夜无人接近周宅','外露区受雨损，缺痕只能在可比较范围讨论。'],['柏正说雨错了，就直接认定柏正枪杀死者','错解释不独自证明杀人，应查造痕、隐匿和当夜行动。'],'逃窗说缺乏路径连续支持，造痕者与死亡责任分别查。','何巡保留窗外比较图，申请核查改动现场的痕迹；没人跳窗重演，也不把泥上缺口当成身体身份。');
 add('c5s05',2,'custody','weighted-package','池中包裹上岸后，哪一项先成立，哪一项仍不能写？',[o('c5s05',0,'成对镇纸只剩一块'),r('c5s05',1,1,'打捞过程记录'),r('c5s05',2,0,'压包物与缺失物'),r('c5s05',2,1,'主动隐匿的组合')],['镇纸、包裹与绳痕支持主动沉藏；内容和沉藏者待清点、见证','主动隐匿的推断有组合支点，不能从水里直接捞出凶手姓名。'],['镇纸是周家的，就能认定周亲手沉包','物品归属不等于实际使用者，仍查谁经手。'],['包裹一上岸就拆散晾开，不必记原顺序','会损失打捞时的组合和包内位置，削弱后续保管链。'],'主动沉藏有支持，包内物与经手仍需下一步核验。','差役先被拉回稳地接受照护，湿包由见证人清点移交干燥处；温放下账线救人的动作按实留下。');
 add('c5s06',1,'custody','wet-ticket-limit','车票和客栈登记出现戴魁的名字，今天该把调查写到哪里？',[r('c5s06',0,0,'湿票只读尚存文字'),r('c5s06',1,0,'入住与到周宅仍待连接'),o('c5s06',3,'熟人核验明日才到')],['登记戴魁相关物件和旅程段，等待熟人与其他身份材料交叉核','名字有查访方向，今天尚无完成遗体辨认的全部依据。'],['票写戴魁就立刻给遗体改名戴魁','携物人与物主可不同，熟人核验尚未取得。'],['用修纸把水毁的字补成完整住址，再直接追人','干燥不能恢复已经不存在的文字，应保留缺失而非生成事实。'],'戴魁相关物件先登记，死者姓名等待独立核验。','湿物分开保护，明日核验保持预约。失去的字仍空着，不因牌桌上成功整理便凭空恢复。');
 add('c5s08',2,'flow','attack-and-staging','周活着出来后，哪三项责任必须分别核验？',[r('c5s07',2,0,'活人身份核验'),o('c5s08',1,'周的求生说法'),o('c5s08',2,'柏正承认造泥沉物'),r('c5s08',0,0,'涉枪材料的限度')],['遭袭、死亡责任、换衣造泥沉包分开；求生解释不替代鉴验','活着证明此前身份误认，不使改现场自动正当，也不判明最后一下怎样致死。'],['周能走出库房，就说明死者一定被他预谋杀害','生还与隐匿不能独自决定原袭击和搏斗情形。'],['只要原先被袭，之后换衣、隐尸与误认都无需处理','后续行为另有后果，须各自说明并查材料。'],'原袭击有材料支持，死亡责任保留鉴验，造假另行认定。','涉枪物件封存，柏正与余雪梅按各自知情时点受询；戴的身份继续核，不能让他替周无名死去。');
 add('c5s09',0,'crosscase','two-identities','两份核验同时到了，怎样避免用一个姓名证明两个人？',[r('c5s09',0,-1,'死者与活人使用不同核验链'),o('c5s09',1,'任务存根到达'),r('c4s17',1,0,'此前仅有身份关联回覆')],['戴用身体特征、旧物与客栈核验；严用任务存根、连续履历与本人','两条链分别回答棺中是谁和周过去是谁。'],['公所证明周是严，便自动证明棺中是戴','活人旧身份与另一死者身份是两项问题。'],['车票已经写戴，今日旧雇主的核验无须保存','今日独立核验正补足此前物件不能独自认人的缺口。'],'死者戴魁与生还者周泊川／严鹤生分别核定，身份不混册。','戴的家属获得真实通知，严开始以本名说明任务与保管；他的身份成立不代表每个历史行动都正确。');
 add('c5s11',2,'flow','fire-command-chain','命令没有写“杀人”，哪些独立材料使烧账行动仍可追查？',[r('c5s11',0,-1,'命令副件与付款传递'),r('c5s11',1,0,'运工亲见带引火物进账房'),r('c5s11',1,1,'火向需另核'),r('c5s11',2,1,'账房与收容所分开')],['接命令流转、同号付款、引火物入账房与火灾记录；亲历范围照留','含混文字不能独自定案，执行和款项可交叉核验具体动作。'],['只凭“清账”语气就认定韩逐项命令杀死每名收容者','文字未给出所有故意和后果，需分指使、执行与蔓延。'],['命令未写杀人，就把所有执行和付款证据删去','文字缺少一句话不取消独立证明的实际行动。'],'M5指向销毁账房材料的指使与执行，收容所遭灾和个体最后时刻不混写。','原件由公所、证人及办案处分别保存，严迟交的责任与保住材料的事实同时保留。温的悲痛不能替未知的最后一刻填字。');
 add('c5s12',1,'timeline','two-disasters','主角童年救援、林照拘押与妻子遇火，应怎样排列？',[r('c5s12',0,0,'妻子请求留下照料的独立记录'),r('c5s12',1,0,'水患、拘押、火灾先后'),r('c5s12',1,1,'严未目击每位遇难者')],['先水患救援，再拘押，后账房起火殃及收容所；妻子留下照料有独立请求','先后解释为何林照能曾救孩子，却在火灾时已无法到场。'],['写成林照火里救出沈砚后当场被捕，情节更连贯','与已核拘押时间冲突，会抹去两场不同灾难。'],['丈夫记得妻子，就把她每个最后动作作为他的目击','林照已被拘押，妻子的请求有别处来源，其最后时刻仍有未知。'],'两场灾难按日期分开，照料者有独立选择，缺失目击不补。','妻子的请求和收件登记独立入卷，温离席片刻后回来换药；沈砚的童年记忆仍须后续身份材料支持。');
 add('c5s13',0,'flow','old-and-new-orders','戴当次来访与十八年前命令出现同名，应怎样划分可追责范围？',[o('c5s13',0,'当次指令和近期付款情况'),r('c5s13',0,0,'两次款项不能同义'),r('c5s11',0,-1,'十八年前原指令链')],['当次送件领款先接到贺属下；韩近期付款用途仍核，不借旧案替新杀令定性','同名网络给方向，具体付款用途和指令必须对应当次。'],['韩旧案有责任，就直接认定每一笔新付款是本次杀令','不同时间和项目没有自动相同用途。'],['用途还没全明，就停止控制贺与保护证人的申请','已核当次关联仍支持采取相应查验与保护，不需等所有旧事结清。'],'旧命令与新袭击分账，现有关系支持独立协查而非私人接管。','何巡按现有材料发控制与协查请求，保留回执。温提出将韩送私人诊所的要求被登记并拒绝，证人先改路保护。');
 add('c5s18',2,'crosscase','public-review-gate','身份已核、韩已移交后，五案材料实际允许进行到哪一步？',[r('c5s16',0,1,'足以申请复查的范围'),r('c5s17',0,0,'温身份独立核验'),r('c5s18',1,0,'公开复查已准备'),r('c5s18',2,1,'接触权限仍受限')],['开始公开复查并保护陈述人；林照身份、旧责任、新行为仍分开','受冤身份不授予私人控制权，也尚未证明任何新袭击。'],['林照身份成立，就允许温单独带走韩补取供词','身份与权限不同，公开核验已具条件，不能由一人取代。'],['五案接起来，便在今天宣告所有旧案人员判决完毕','材料支持申请复查和逐项回应，不等于已经完成全部审理。'],'五案成果归档，公开复查获得真实入口；私下会面仍是未决申请。','旧案原件照原处封存，公开陈述已发通知。你可在保存五案成果后继续核对未决会面，不是因同情就给任何人定罪。');
 // Case 6: use lived evidence, then prove current actions without a confession.
 add('c6s02',1,'custody','document-and-access','在出事以前，交接副件与房间结构能让你确认什么？',[r('c6s02',0,-1,'转乙六的用途与保管'),r('c6s02',1,-1,'首次可查空间'),r('c6s02',0,0,'正本权限未转交')],['转乙六不是北仓原件；只有指定接收用途，递口过不了人，屏风后无出口','把物件、权限和可行通路在事前分清，后续变化才能实查。'],['温持问诊预约，就能凭任何副件带走韩','问诊与押送权限不同，副件仍需双人核验。'],['屏风遮住视线，就暂把其后视为可能通外的秘道','已经实查是洗手架和实墙，不能因遮挡自造出口。'],'转乙六用途和原状先记，普通门闩、固定栅和递口事前可查。','宋绮留下正本保管处和副件编号，温按问诊预约来访；首访记录不因后来的混乱重画。');
 add('c6s04',2,'hypothesis','not-alibi-for-whole-night','“叫声时温就在我身边”可以覆盖哪一段？',[r('c6s03',2,0,'何巡先收到求救才敲门'),r('c6s04',0,0,'共同目击的实际区间'),r('c6s04',1,0,'插闩前机会')],['只覆盖共同廊下所见；受伤求救更早，改查插闩前接近者','真实的不在场可以被错误延伸，缩回范围不等于当场定凶。'],['温急救有效且与我同听叫声，就对整晚免责','救治和叫声时段都不能证明更早的行动。'],['内闩从里面锁着，就证明窗栅后必有秘密出口','求救已在叫声前，先查两次事件，不必发明与事前图冲突的通路。'],'撤下整晚免责，保留廊下目击；首次受伤与插闩的先后继续查。','沈砚主动改正自己担保的范围，何巡排查全部访问者；宋绮由独立医者照护，不被迫当晚补出一张脸。');
 add('c6s05',2,'timeline','two-events','把三份当晚记录排好，哪一种顺序不需要虚构逃窗？',[r('c6s05',0,-1,'阿豆的回单交接'),r('c6s05',1,-1,'独立值班先后'),r('c6s05',2,0,'四个事件分别记')],['首次受伤→递求救纸→温到公共廊下→敲门后重响','求救纸明确已受伤，且先到值房；后来的叫声不必就是第一击。'],['温到廊下→重响时首次受伤→才写求救纸','与阿豆先送纸、何巡再敲门的两份独立记录相反。'],['递求救纸→重响→温到廊下；先据此查重响后的接触','值班人亲见先收纸、后见温、再听重响；重响不在温抵达以前。钟的少许误差不会颠倒被独立见到的顺序。'],'两个相隔事件成立，廊下目击不覆盖首次受伤；时钟误差保留。','何巡修正时间表，阿豆不再被说成听见重响后才来报信；调查转向早段接触和失物，而非无限寻找逃窗机关。');
 add('c6s06',1,'testimony','injured-witness','宋绮怎样说明密室形成，又没有替调查认出施袭者？',[r('c6s06',1,-2,'宋绮背身受击与自己插闩'),r('c6s06',1,0,'温称受伤前已离开'),r('c6s06',1,-1,'另两访客的核验')],['她受伤后递信并插闩，后起身跌倒；没见脸，温离室仍需独立查','解释密室不等于证明第一击者，任何人的声称离开仍待支持。'],['宋觉得温没走，就把证词写为亲见温举手','她明说背身且未见脸，不可用怀疑替换亲历。'],['另两人有预约，就把未登记进入的可能一并清除','预约只能覆盖已登记活动，仍须失物和实际机会补证。'],'密室在首次袭击后形成，后来的重响另有起身跌倒解释；施袭者仍待核。','宋绮亲自核准口述栏，后续问话按她休息安排。温的告辞与离室在表上分成两格，没有借旧恩合并。');
 add('c6s08',2,'custody','missing-transfer','逐件清点后的首要处置是什么，纸角现在又能说明什么？',[r('c6s08',0,-1,'失物是转乙六'),r('c6s02',0,-1,'事前编号与用途'),r('c6s08',1,1,'纸角不能认拿件者'),r('c6s08',2,0,'路线已经作废')],['确认交接副件丢失，作废旧路线并封存纸角；待找回副件再比对','失物提示控制韩的机会，纸角暂不提供拿件者身份。'],['纸角纤维能认出温的手，立即宣告他袭击宋','物件对比不能识别某人的手，更不能替代首次施袭链。'],['五案真相全被偷走，只能靠温的回忆继续','清点显示五案副本都在，原件也分处保存，失物不是万能真相册。'],'旧路线失效，转乙六和纸角保持独立编号，五案原件仍可回查。','负责人改为原地保护并通知接收处，旧副件不能再接走韩。这个实际防护稍后会拦下失窃件的用途。');
 add('c6s09',2,'decision','restrict-without-bait','排查访问者时，哪种安排真正降低危险又保留核查？',[r('c6s09',0,0,'暂停探视'),r('c6s09',1,1,'外窗口与内区权限分别记'),r('c6s09',2,1,'旧受害陈述保留')],['收回临时探视凭条，外窗只收物不通内区；保留各人原稿与独立守卫','限制机会依据当前查验，不烧材料，也不用活人作诱饵。'],['让温自由探视，看他会不会再动手以便拿现行','已有保护可以执行，不能故意撤除让人再次受害。'],['温被排查，就撤掉他的旧案受害陈述','当前怀疑不取消既有旧案证据和陈述权利。'],'访问限制与外侧投递权限分开，原稿照常保存。','温交还凭条，韩留在独立保护内区；接收窗口保留双人核验，之后递来的旧件会被登记而不是照办。');
 add('c6s11',2,'custody','actual-presentation','接收窗口的新记录，比温说错窗逃多证明了什么？',[r('c6s11',0,-1,'双人亲见递转乙六'),r('c6s08',0,-1,'先前失物登记'),r('c6s11',2,1,'温此前否认拿件')],['证明温实际递来失窃号副件并想依旧件接人；查原件与否认冲突','有独立当前动作，不再只是错误假说；物件同一性继续比封角。'],['递过副件，就可以把宋没见脸的证词改成亲眼认温','新证据可补链，不能重写旧证人的视线。'],['旧件作废未接走人，就无须登记递交者','未能实现目的仍留下实际递交、持有与请求的可查行动。'],'温在双人见证下递交同号纸件，接人请求被拦；物件同一性与取得来源继续核验。','当班人扣留纸件并通知何巡，韩没有被交出；调查转向纸件的完整交接与温的来源解释。');
 add('c6s12',0,'custody','paper-match','纸角合上后，哪一层推断得到加强，又有哪一层仍须合看？',[r('c6s12',0,-1,'扣留件直接交接与拼合'),r('c6s06',1,-2,'背身受击的证词'),r('c6s11',0,-1,'亲手递交的双人见证')],['确认温递的是失窃原副件；与早段机会相合，第一击仍据全链核验','编号、撕裂边和独立交接证明同一物件，不是仅凭一张相似纸。'],['拼合成功就宣布纸纤维直接证明谁击伤宋','纸的同一性不等于动作目击。'],['未亲见第一击，就忽略现有持件矛盾等待供认','证据可以累计且分别证明，不必等一份包办全案的独白。'],'失窃副件从温递出到查验的来路可核，第一击仍保留完整证据范围。','纸件留在专人处，通知内区查接触；小院出现的新动静另起现场，不能为了等温解释而延误制止。');
 add('c6s13',2,'flow','new-violence','这次小院和内门的事，哪些已由独立亲历支持，不必借旧冤定罪？',[r('c6s13',2,-2,'后勤员亲见被打夺钥匙'),r('c6s13',2,-1,'守卫亲见控制现场'),r('c6s13',1,0,'越区钥匙停止使用')],['后勤员被袭夺钥匙、内门进入与控制韩另成新链；先终止控制','当前暴力有多人亲历，既不靠林照身份，也不需要先判明宋室内每个细节。'],['温受过冤，就把束缚韩写成合法保护','受害身份不赋予私人伤人和强制转移权。'],['第一击还需核，就不能阻止这次已见控制','新案事实可以独立处理，不能以另一处待核为由延迟救人。'],'第二次伤人、夺钥匙和控制有独立见证，越区缺口即时停用。','守卫接手内门，你们将伤员送出并准备解除韩的束缚；温不再取得转移决定权。');
 add('c6s15',1,'crosscase','rescue-and-accountability','温拒绝解释时，怎样同时保住韩的旧责和今天受害者的责任材料？',[r('c6s15',0,0,'旧案仍公开'),r('c6s15',1,0,'两次事件分别证明'),r('c1s08',1,0,'温当年先救梁福'),r('c6s14',2,0,'沈砚以同一道理救韩')],['继续查旧案，第一击按全链核，第二次按独立目击提交；救人不撤账','前案亲历的先救人原则在此有后果，不要求喜欢或原谅被救者。'],['韩今天受伤应获救，就把十八年前责任也删除','保护生命与追责是不同处置，今日救助不改旧证。'],['温不供认，就用停止救治逼他说出全部真相','拒绝供认不消灭独立目击，保护不能拿来交换供词。'],'旧案与当前伤害分别继续，温的善行保留也不抵扣伤害。','何巡接管现场，温不能自行选择对质地点和答案；韩在保护下进入复查，宋与后勤员照护继续。');
 add('c6s16',2,'crosscase','six-independent-cases','六案合卷时，哪一种总叙述经得起你一路亲历的材料？',[r('c1s16',0,-1,'陶的犬舍旧鞋'),r('c2s13',1,-2,'惟善的抵押和款项'),r('c4s12',1,0,'秦与素禾的独立链'),r('c6s13',2,-1,'温当下被亲见控制')],['六案行为人和动机各有证据；温追旧案、真实救人，最后的越界另证','连接由旧凭据和人的选择形成，不能将独立犯罪重写成温全盘安排。'],['温最后成为对手，所以之前每案必是他排好的测试','前案有各自独立筹备和行动链，当前暴力不能倒推他操纵一切。'],['前五案他多次救人，当前目击与持件矛盾便不可信','既有恩情不取消新取得的独立材料。'],'六案分列当前行为与北仓交接，不缩成好人坏人一项总评。','宋绮按自己能承担的方式核阅总清单，她“没看见脸”的原话仍在；无人因结案被迫撤回伤害或承认宽恕。');
 add('c6s18',1,'custody','final-records','同行到此结束，哪一种保存办法能让下一位查案人继续核验？',[r('c1s17',2,0,'M1顾家原件'),r('c3s16',2,0,'M3分处两版'),r('c4s18',1,0,'M4原信与副本'),r('c6s18',1,0,'最后一次原件去处核对')],['核各处原件与认证副本清单，交公开复查或另存见证处均保留来源','保管选择影响查阅安排，不改变查实内容和各处原件。'],['把所有原件交给最信任的一人，其他来源可丢弃','单人保管会切断已经建立的独立回查，信任不能替来源。'],['水中仍有未解倒影，暂停全部人间证据直到解释清楚','倒影没有提供可核证词，不推翻物件、时段和亲见行动。'],'六案原件有门牌、认证副本有出处，未解意象不替证据翻案。','你把后续查阅安排交清。受害者自行决定是否留灯，未写出的悔过和原谅仍由本人决定，不充当通关口令。');
 // A second editorial pass removes moral/common-sense answer cues. Each wrong
 // hypothesis starts from a real clue and is defeated by another visible fact.
 function rewrite(sceneId,prompt,refs,good,bad,other){const n=nodes.find(n=>n.sceneId===sceneId);if(!n)throw Error('Missing rewrite '+sceneId);Object.assign(n,{prompt,refs,answers:[good,bad,other]});}
 rewrite('c1s09','把寄送簿和柳的两次联络排在一起，哪一种先后能同时解释它们？',[r('c1s09',0,0,'第一次约见与后来取消'),o('c1s09',1,'柳认出自己的信'),o('c1s09',3,'陶后来的口信'),r('c1s09',1,1,'底簿只记给顾的邀请')],['柳先寄邀请，陶后来另叫她别去','沈砚核问的第一封邀请在先，柳所说陶“另想办法”的联络在后；现有底簿只有邀请，不是给顾的取消通知。'],['陶先取消会面，柳再写信重新约顾','这把柳说明的两次联络倒了过来；她将陶的口信放在自己寄出邀请以后。'],['柳同时给顾寄了邀请与取消两信','底簿与残信支持的是邀请，眼前未有第二封给顾的取消信；后来的联络对象是柳。']);
 rewrite('c1s16','陶要接近承安，旧堤死者却是宋旺。哪条目标转移最符合已找到的物件？',[r('c1s16',0,-1,'犬舍找到承安旧鞋'),r('c1s16',1,0,'旧衣交付与穿衣人'),c('c1s12',0,'宋旺身份核验'),r('c1s13',1,-1,'新鞋被退，改催穿过的')],['取有使用痕迹的物，追赶随旧衣到了宋旺身上','退新要旧、犬舍保有旧鞋，加上旧衣转给宋旺，支持追赶被目标物带向换了穿衣者的人；这不是按承安的脸认人。'],['宋旺带走那只旧鞋，犬才追到藏身处','旧鞋已在犬舍清点，并非在宋旺身边找到；实际交给宋旺的已知物是旧衣。'],['陶只认顾家衣式，取新旧鞋是为核服饰样式','新鞋与旧鞋同属承安，付钱人却退回未穿新鞋、专催穿过的；这种选择不能由衣式相同解释。']);
 rewrite('c2s09','映棠看见谢取灯，却看不到后廊。哪处查访最能补上离开她视线后的第一段？',[o('c2s09',1,'取物目击'),o('c2s09',3,'后廊被遮住'),r('c2s08',0,1,'小梅只在交洗后发现漆痕'),r('c2s05',2,-1,'渡口盘问的范围')],['回后廊查当夜停留者与经手人','空白从后廊遮挡处开始；小梅的发现已在交洗后，渡口盘问也不覆盖宅内交付。'],['到洗衣处重查小梅第一次发现漆痕','它能重核接触门框，却发生在衣物交洗时，补不上谢取灯后进入后廊的那一段。'],['去渡口查三人盘问后是否再次返回钱宅','三人返回的可能仍可另查，但已见取物者是谢；当前首个具体空白在谢进入后廊之后，先核那里能直接接续物件。']);
 rewrite('c2s13','化名、委托人与付款分在三栏。哪条路线最能把灯心接离谢的手之后？',[r('c2s11',1,0,'后廊代存原话'),r('c2s13',1,-2,'代办说明与物样付款'),r('c2s13',1,-1,'两个机构的原单')],['谢交存→惟善委托代办→款进善堂周转账','店伙支持前段代存，代办独立说明惟善委托，收当与钱庄将后段物样、款号接合。'],['谢委托代办→代办借善堂账代谢收款','材料没有谢与代办接触；代办指明委托者是惟善，付款去向也由惟善安排。'],['代办自行拿物→惟善仅替代办保管货款','这能利用化名掩护的表象，却解释不了代办对事前委托和惟善指示入账的说明。']);
 rewrite('c3s05','陆家称照宁昨日清晨死亡。眼前三处记录把调查首先推向哪一个缺口？',[r('c3s05',2,-1,'死亡单、签货与车行时段'),r('c3s05',1,0,'送货人只见侧门这一段'),c('c3s04',0,'素秋死亡与照宁失约原分两页')],['午后还在侧门的照宁，上车后去了哪里','亲签、说话和出车同落午后，与清晨死亡相冲突；送货人没见后续，车行是下一段实际去向。'],['照宁清晨的遗体，是否午后才送出陆宅','午后的独立记录包括她本人说话和拒绝上车，不只记录了一件被运走的物。'],['出车表是否只是接走素秋的记录','该条与陆宅侧门送货人的亲见相接；素秋病故与停灵另有记录，不能用同日出车合掉两人。']);
 rewrite('c3s15','两份同号保证书的这一处改字，会让哪类本不应继续发生的领粮记录看起来有效？',[r('c3s15',1,0,'当年独立收件副本'),r('c3s15',2,-1,'已故止领与仍居续领'),r('c3s15',0,0,'重装只说明装订变化')],['该领粮户死亡之后仍列在名下的支出','原副本已经止领，底册却把状态改成仍居续领；改变的是死亡后的资格，后续要查哪笔账据此发生。'],['该领粮户死亡以前尚未领完的份额','两版关键差异在已故与仍居，不是生前份额多少；眼前也没有补发欠额条款。'],['另一户迁入北段后新取得的领粮额','两份同号材料对应同一领粮户，没有出现迁入人或新户号，不能把状态更改解释成另户登记。']);
 rewrite('c4s11','把21:50的码头记录与22:05—22:15的声响区间叠起来，哪条夜间行程仍值得追？',[r('c4s11',0,-1,'约十分钟的声响区间'),r('c4s04',1,-1,'码头连续在场与四十分钟往返'),r('c4s11',2,0,'秦从侧梯下来')],['秦睡下前后是否仍从侧梯进出书房','送炭人约22:15见秦下侧梯，与22点已睡冲突；许由两名值班员确认21:50起连续在码头。排除许依赖连续在场，不能只拿往返时长替代目击。'],['许21:50后离开码头，单程赶到书房再返回','仅看距离会留下单程到宅的可能，但两名值班员分别确认许持续处理故障直到次日，未留这段外出窗口。'],['秦22:15才下楼，查他声响以前离宅的路线','下楼目击并不说明他此前已离宅，反而把他接到案发区间末端的侧梯。']);
 rewrite('c4s12','秦称夜里已睡、早晨只送素禾到办事点。哪组材料同时击中这两段说法？',[r('c4s11',2,0,'夜间侧梯所见'),r('c4s12',1,0,'泵房出入与车夫'),o('c4s07',1,'车夫所记东堤去处'),r('c4s12',0,-1,'枪械材料多人可接触')],['侧梯的22:15目击；泵房两人进、秦独出与无办事点记录','第一项反驳睡下时点，后一组将次晨路线从所谓办事点接到泵房；两处各有独立见证。'],['枪柜擦拭布；素禾曾经谈起那捆旧信','擦拭布多人可接触，谈信也不是泵房出入；它们可辅助，却不能分别击中两段具体行程。'],['姐妹隐瞒许来访；秦签收过云岚的邮件','这些支持秘密关系与通信控制，仍缺秦夜间及次晨实际所在，不能替两段说法完成反驳。']);
 rewrite('c5s03','若杀手真从窗台跳进泥地后离开，哪一处最难用昨夜大雨解释？',[r('c5s03',0,-1,'檐下旧印与落足区'),r('c5s03',1,1,'固定比较位置'),r('c5s03',2,0,'窗台与外侧缺口')],['檐下旧鞋痕仍清楚，却没有接住窗台来路的新落足','同一遮雨区仍留可比较旧痕，不能用露天雨洗解释檐下所缺的那一步。'],['露天路段几乎没印，却在窗台留下了泥','露天本就受雨损，单凭这里缺印无法区分真的逃离与伪装。'],['窗台泥朝外，说明来者进屋时也走了同一扇窗','朝向可提示去向，但不能证明来路；这项也解释不了檐下没有相接落足。']);
 rewrite('c5s08','窗外不连贯的泥、池中衣包、活着的周，哪一种现场形成顺序能同时容纳？',[r('c5s07',1,0,'周一直藏在库房'),o('c5s08',1,'周说明搏斗后求生'),o('c5s08',2,'柏正承认造泥沉衣'),r('c5s08',0,0,'涉枪现场仍有鉴验局限')],['涉枪冲突后换衣、造逃窗痕、沉包，周藏入库房','柏正认了造泥沉物，活着的周和库房结构给出藏匿去处；枪击最后过程仍须材料鉴验。'],['周先藏库房，戴再换上他的衣服自行跳窗逃走','棺中遗体和现场物件尚在，戴不是已逃走的人；柏正也承认泥是事后制造。'],['外来杀手先从窗逃走，柏正只把遗留衣物沉池','窗外缺落足且柏正承认造泥，不能把已查为人为布置的逃窗痕继续当真路线。']);
 rewrite('c6s05','把纸上的原话与三栏时辰相对照，哪一种重建能解释阿豆为什么先去找何巡？',[r('c6s05',0,-1,'阿豆实际送出的原纸'),r('c6s05',1,-1,'院钟与收件记录'),r('c6s03',2,0,'何巡受通知到门前')],['宋受伤后递纸，温随后到廊下；18:24重响是另一件事','18:18收下的纸已写受伤，温18:20才在廊下被见；重响到18:24才发生，不能把首次受伤放在那一刻。'],['宋先请何巡来，18:24重响才是第一次受伤','如果18:24才首次受伤，18:18已交到值房的原纸就不该写着“我受伤了”。这不是后来补记的口信。'],['温已陪沈在廊下，宋才受伤递纸，接着传来重响','这保住了沈砚的整段担保，却倒置收件18:18与廊下相见18:20；两项由同一院钟和在场值班人相核。']);
 rewrite('c6s12','如果温拿来的只是按旧号另抄的一份，哪项比对最直接与这个解释冲突？',[r('c6s12',0,-1,'订孔、撕裂边与连续交接'),r('c6s02',0,-1,'事前副件与正本分处'),r('c6s11',0,-1,'当班人亲收温递来纸件')],['原订孔与撕裂边能接回宋桌边同一封角','抄号能复制文字，却不能解释已封存原纸角与实体断边相接，且交接过程未换件。'],['转乙六号能与旧转移安排逐字对上','另抄旧件也能保留编号与文字，这一项本身区分不了原件与抄件。'],['温把纸递给两个值班人，请他们按旧路线交人','递交与请求证明他使用这份文件，但不独自区分手里是原纸还是抄件。']);

 rewrite('c1s07','衣服早已送出，问灯后藏身处却空了。要再缩小宋旺离开的时段，哪条查访最直接？',[c('c1s06',0,'宋嫂送过衣服'),r('c1s07',2,0,'梁福不知换地方的时间'),c('c1s06',1,'送衣早于问灯')],['查最后一次亲手送饭时，有没有见到宋旺','送衣只给物件一个早限，梁福也不知换藏；最后亲见人在此的送饭记录才能缩小离开时段。'],['向顾承安核他清行李交出旧衣的时刻','这能使衣服的前段更准确，却仍不知道后来穿衣的人何时离开藏身处。'],['按问灯结束的时刻查盐滩上经过的人','问灯是你们调查家仆的时刻，材料未显示宋旺此时才动身，以它为离开起点可能漏掉更早离开者。']);
 rewrite('c1s12','尸体穿着顾承安的衣服，衣物最后一段已知转交发生在哪里？',[c('c1s06',0,'宋嫂说明先前送衣'),r('c1s12',1,0,'梁福亲手交付'),r('c1s12',2,0,'宋嫂对死者的辨认')],['梁家接下旧衣后，将它送给了宋旺','梁福说明少爷给他们、他们又给宋旺，宋嫂也独立说明早已送衣；最初主人并非最后穿衣人。'],['顾承安清行李时，直接把衣服交给宋旺','顾承安交给的是梁福，中间经梁家转送；省掉此段会误认最后接触关系。'],['梁家在发现遗体后，才拿顾承安衣服去辨认','衣物交付在问灯之前就已发生，早于发现遗体；不是辨认时才添上的物件。']);
 rewrite('c1s13','哪组相互独立的材料把“陶有继承利益”接到了遇害前的实际准备？',[r('c1s13',0,-1,'旁支资格的条件'),r('c1s13',1,-2,'犬笼运单与供肉账'),r('c1s13',1,-1,'交鞋后门'),r('c1s10',0,-1,'书塾关系回函')],['犬笼送养药屋的运单、陶的供肉款、小栓交鞋的后门','三段分别由运犬者、账本及交鞋人支持，且犬只准备早于遇害；它们把利益连到具体安排。'],['书塾所记婚姻、江蘅的警告、顾家旁支资料','这解释关系欺骗和利益，尚缺运犬、取鞋等实际筹备环节。'],['顾宅夜间灯号、梁家送衣、宋旺离开藏处','这条路能解释家仆接济与后来衣物流转，未把陶接入遇害前的养犬准备。']);
 rewrite('c1s18','去钱家调原凭据，哪一项最能排除调来的是顾家另一笔借款？',[r('c1s17',1,0,'原清册的编号与日期'),r('c1s17',2,0,'副本核对见证'),r('c1s18',2,0,'预约核对对象')],['“北仓抵字第十七”与该条日期同时吻合','同号同日指向同一笔事项；仅有人名或同族名目可能命中多份记录。'],['凭据上同时有顾家的名字和钱家的印','双方可能不止一笔往来，名字和印只能缩小范围。'],['附页出现沈怀舟熟悉的署名','他的署名给誊录线索，不能单独证明正是此次抵押。']);
 rewrite('c2s02','宴前哪一个动作，会让衣物沾新漆，却未必接触灯心？',[r('c2s02',0,0,'灯座和新漆位置分开记'),r('c2s02',0,1,'小梅指搬物经过的门边'),r('c2s02',2,1,'进出分别登记')],['从刚补漆的门框旁搬东西通过','小梅指出自己搬物所走的门边；门框和灯心登记为不同接触处。'],['直接在灯座旁核对灯心的尺寸','灯座处没有被记为补漆位置，不能把灯旁动作直接对应门框漆。'],['在院中等雨停后从原地离开','仅在院中等候尚未给出与门框接触的那一步，仍需实际路线。']);
 rewrite('c2s04','哪一条衣物路线与漆的位置、小梅的收衣说明同时相合？',[r('c2s04',1,0,'漆痕指向门框'),r('c2s04',2,0,'交洗批里的谢外衣'),r('c2s04',2,1,'收到和藏起分别询问')],['外衣擦过门框，进入交洗批，后被小梅收起','漆痕定位接触，交洗说明接住衣物来源；目前仍须继续问实际穿衣人与各段时刻。'],['小梅在衣箱给外衣补漆，再将它放回门边','新漆来源在当夜门框，现有接收说法是交洗批；没有从衣箱补漆再放回的步骤。'],['外衣先藏在小梅箱中，宴后才首次经过门框','她说明自己从交洗批收到已有漆痕的衣服，这将擦漆放在收起之前。']);
 rewrite('c2s08','小梅的亲口说明把她的判断起点放在哪里？',[r('c2s08',0,1,'交洗时发现漆痕'),r('c2s08',1,0,'发现与藏衣的先后'),o('c2s08',1,'她承认藏谢的衣服')],['交洗时看见漆痕，猜谢取灯，随后藏衣','她明确把所见放在交洗与漆痕，取灯是后来推测，不是当夜站在灯边的目击。'],['宴夜看见谢带灯出门，交洗时才决定藏衣','这把她没有亲见的带灯出门提前变成判断起点，与本人说明冲突。'],['先替谢藏衣，醒来后才听别人说衣服有漆','她说明发现漆痕是藏衣的原因，时间在交洗时，不是醒来后才第一次得知。']);
 rewrite('c2s10','叶成带来的交接记录与周济补答，使谢的记忆空缺多出哪条可查原因？',[o('c2s10',1,'当夜给药交接与剩余包'),r('c2s10',1,0,'周济说明没有充分告知'),r('c2s10',0,0,'药铺与记录对应')],['谢当夜已被给药，却没被充分告知','药铺交接、余包和本人补答支持这个行为，之后仍应靠路线见证判断取物及交付。'],['谢自行从药铺另买一包，回宅后独自服用','现有对应交接及周济说明指向周的给药，未出现谢另购的一笔。'],['药只备好留在屋里，当夜没有实际交给谢','周济对说明栏的补答与当夜交接相接，不支持仅备而未给的解释。']);
 rewrite('c2s11','店伙这一段亲见，给失物路线接上的两个人是谁？',[o('c2s11',2,'店伙见后廊交包'),r('c2s11',1,0,'听见代存请求'),r('c2s11',0,1,'映棠视线到此被挡')],['谢把包递出，惟善在后廊接下','店伙直接看见递包方向，并听见代存请求；它接在映棠视线终点以后。'],['惟善先把包给谢，谢再带往灯座方向','这把店伙亲见的递出与接收者颠倒了，不能由后来谁有物件倒填前段。'],['小梅把包交惟善，谢只是同时路过','小梅在先前材料中经手的是交洗衣物；本段店伙见到的交包人是谢。']);
 rewrite('c2s12','已翻开的基金账，支持哪一种事件顺序？',[o('c2s12',0,'账面亏空日期'),o('c2s12',1,'失物不是短款首次出现'),r('c2s06',0,1,'月底交账期限')],['基金先有短款，月底交账在逼近，宴后才失灯','短款落在宴前；期限解释后来催促为何紧，但抵押行为还要查独立记录。'],['灯心先失窃，月底交账时才出现基金短款','将短款放到失物以后，与宴前已缺的原账相反。'],['月底交账已经结束，惟善才为下一期募集灯心','惟善说明月底必须交，交账仍在前面逼近，不是已结束的事。']);
 rewrite('c2s15','前半段的“先替我放妥”，在哪一环变成了没有对应委托的新处置？',[r('c2s11',1,0,'代存原话'),r('c2s13',1,-2,'代办与款项'),r('c2s15',0,0,'三段对照')],['惟善接存以后委托代办抵押、把款汇入周转账','代存原话未包含抵押，代办及付款却证明新处分，转折发生在惟善接物之后。'],['谢走近灯座取物时，已经办理收当和付款','取物是前段目击，收当处代办及付款对应惟善安排，不能提前到谢伸手那一刻。'],['小梅收起沾漆外衣时，同时替灯心更换了收当人','小梅当时经手的是衣物，现有收当与付款链没有把她接到更换收当人的位置。']);
 rewrite('c2s18','旧抵押存根夹页哪一项，把下一次查访指向陆家而不是收当灯心的机构？',[r('c2s17',0,0,'M1同号的旧存根'),r('c2s17',1,0,'陆存礼出具保证'),r('c2s13',1,-2,'新近灯心收当另有记录')],['旧存根夹页上陆存礼保证书的编号','它是这笔旧抵押使用的身份保证索引；新近灯心收当物样和善堂账号属于另一笔。'],['灯心入库的物样和莲瓣缺口','这能追已追回灯心的保管和收当，不能定位十八年前陆家的保证底册。'],['善堂周转款到达钱庄的回执号','它对应惟善这次抵押后的款项，不是旧抵押所依的身份凭据。']);
 rewrite('c3s03','照宁抱着账簿出来时，她实际提出的两件事是什么？',[o('c3s03',1,'本人说明被催转股'),r('c3s03',0,0,'离居与股份'),r('c3s03',0,1,'本人说明财产仍保有')],['搬离陆宅，但不把股份转出去','她明确要离居、拒签转股，并补充没有不要自己的东西。'],['转出股份，以此换来搬去染坊','她说的是不签而且要搬，并未同意把财产作为离开的交换。'],['暂离染坊休养，让家中代管股份','她希望离开的是陆宅，账簿和股份仍要自己处理，不是暂离工作交家中代管。']);
 rewrite('c3s06','棺中的人若确为素秋，哪条运送链已经从两个保管点接合？',[r('c3s04',2,0,'冯出现在领尸登记'),r('c3s06',0,0,'停灵与陆宅独立交接'),r('c3s06',2,0,'病故前连续护理'),o('c3s06',1,'姨母从未委托冯')],['外院病故后到停灵所，冯领出，再由陆宅接收','护理给起点，停灵领出与陆宅收进给两端；姨母否认使所谓委托成为另一个疑点。'],['照宁在陆宅病故，冯先送停灵所又原路领回','该护理链从外院的素秋开始，并非陆宅照宁病故；也与午后照宁活着的见证冲突。'],['素秋姨母在外院领走，随后自己送往陆宅','领尸登记实际出现的是冯，姨母否认委托，更无自己送往陆宅的交接。']);
 rewrite('c3s09','院方继续用“白素秋”应答时，哪一条查找路线最可能找到被换名的活人？',[r('c3s09',0,-1,'床号、押金及陆宅来处'),r('c3s05',2,-1,'已核陆宅侧门出车'),c('c3s06',0,'素秋遗体已核')],['按乙三床和四一押金查续收者，再核陆宅侧门来人','名字可能被沿用，但旧床和押金连着实际接收位置，车行又给出陆宅起点。'],['按白素秋姓名回公共停灵所，重查是否有人领走','停灵所和棺中身份已接合，当前新条目指的是病故之后仍在用的床位，活人不在那条已闭合的遗体链。'],['按寿衣尺寸回店查订做时量衣者的住所','它能追先前订单，却没有乙三续收页这样指向当前所在的具体位置。']);
 rewrite('c3s10','哪组材料最直接回答乙三床上的活人是不是照宁？',[o('c3s10',1,'布条点出的旧账误'),r('c3s10',0,1,'按原册核账'),r('c3s10',2,0,'身份链'),r('c3s09',1,0,'车夫没看清脸')],['未公开的原账误、秋岚核认、陆宅侧门接送记录','原账误能回查，熟人能认本人，接送记录将人从原住所接到院；三项回答活人身份。'],['乙三床号、四一押金、院账写的白素秋','这些锁定搜索处，却可能全部来自同一份被沿用的旧籍，不能单独回答床上是谁。'],['外院护理、姨母认出的旧衣、停灵所领尸簿','这组已经用来确认素秋遗体，不能把另一人的身份材料直接套给眼前活人。']);
 rewrite('c3s12','哪一项最难与冯所谓“临时信了家属，顺路送医”同时成立？',[r('c3s12',0,-1,'病故后、接人前的旧籍款'),r('c3s12',1,0,'乘车人要求去染坊'),o('c3s12',1,'冯的解释')],['素秋病故后、接人以前，就付了旧籍续用款','临时误送不足以解释提前指定已病故者旧床旧籍的付款，尤其乘车人还要求去染坊。'],['车夫承认从陆宅侧门接到一个没看清脸的人','这与冯的家属送医说可以并存，单凭接人地点还区分不了自愿与预谋。'],['主管在问话时愿意交出一张更名便条','事后交便条尚需核来路，区别预先准备与临时处置的强点是先于接人的独立款项。']);
 rewrite('c3s13','陆存礼称只是儿子办错了。眼前最值得单独追查他的哪一个时段？',[r('c3s13',1,0,'得知疑点后仍催清算'),o('c3s13',1,'以还股换撤诉'),r('c3s08',0,0,'股份处分契约')],['已知死亡记载有疑点后，仍推动股份清算的时段','这条材料直接把陆本人接到知情后的处分；儿子最初接送另有其他来源。'],['素秋病故前，陆安排她住进外院的时段','现有材料没有陆安排素秋入外院这一段；不能用陆后来催办填补它。'],['照宁出院以后，陆恢复她染坊工作的时段','已见要求是拿还股换撤诉，不是他帮助恢复工作的记录；需查的是疑点后仍催清算。']);
 rewrite('c3s16','旧工资和收件信息与署名相合后，沈怀舟最先能被接到哪一种经手位置？',[r('c3s16',0,0,'工资与收件核查'),r('c3s16',0,1,'誊录付款的范围'),o('c3s16',1,'陆承认让人重誊')],['按材料受雇重誊、交付文书的经手者','工资与收件把署名接到具体工作，陆又承认安排重誊；是否明知、受何指令还要查当年的交付。'],['只把密封件运到邵行、从未接触正文的送件者','誊录付费和重誊安排指向抄写工作，不能将他只放在运输位置。'],['出具身份保证、决定领粮资格的保证人','现有保证书与陆的出具手续相接，父亲证据首先是誊录工资和交件，不是保证权。']);
 rewrite('c3s18','为了追两版文书究竟怎样送达，邵家回函哪条信息最值得用来发下一封查询？',[o('c3s18',1,'严鹤生与护运公所地址'),r('c3s18',0,0,'M3差异与待查范围'),r('c3s16',0,0,'父亲工资和收件')],['严鹤生的送件姓名与护运公所中转地址','它直接提供投递经手与可联系处，下一步核原簿和本人，而非再从字迹猜路线。'],['陆家保证书封面的装订孔位置','孔位指向重装，没有投递人或现可发询的地址。'],['沈怀舟工资记录中已经核过的笔迹样式','笔迹可辅助认经手，但无法替送达行程提供下一位可查的人。']);

 rewrite('c4s02','钥匙在云筝手里时，谁仍可能不经她开门而到书房内廊？',[r('c4s02',0,1,'云筝只说明自己拿钥匙'),r('c4s02',1,0,'侧梯连书房内廊'),r('c4s02',2,0,'发现后多人的进入')],['走公开侧梯送卷的人','侧梯直接连内廊，秦平日从那里送卷，不需先取云筝手中的备用钥匙。'],['清晨主人被发现后才进来查看的人','清晨接触虽需登记，却不能说明前一夜怎么绕过钥匙。'],['只能是曾借走同一把备用钥匙的人','该判断把钥匙当成唯一入口，无法容纳已在图上的侧梯。']);
 rewrite('c4s05','秦说云岚因遗产即将改变而动手。眼前哪份记录最能检验她当时知道多少？',[r('c4s05',0,0,'讨论预约尚未签署'),o('c4s05',2,'云岚只知口头威胁'),r('c4s05',1,0,'经办预约的人'),r('c4s05',1,1,'秦承认经办')],['改立预约的经办与通知记录','它能核谁知道具体讨论日期；目前秦经办有知识来源，云岚承认的仅是口头威胁。'],['已经签署生效的新遗嘱正本','外聘见证人确认只是预约讨论、未签；这份已生效正本并不存在于当前材料。'],['云岚半年前的婚姻见证书','它解释被反对的关系，却不证明她得到过这次改立预约通知。']);
 rewrite('c4s06','素禾没有回来，她的箱子又被翻乱。哪一件留下的物品能把查访接到宅外一个独立记录点？',[r('c4s06',0,0,'箱内没有事前清点'),r('c4s06',1,0,'邮局可核寄书安排'),o('c4s06',1,'未拆书包和收条')],['带日期的寄书收条，去邮局核寄件安排','收条提供独立机构与日期；它不能证明实际去了邮局，但可向外接续她最后的安排。'],['箱中现在少的衣服，去衣铺查她当天买过什么','没有事前清点无法确认少了哪些，当前尚无衣铺交易与她的对应条目。'],['家人说短少的钱，去渡口查她购票数额','短少本身尚未确证，不能据一个不明数额定位她实际买过哪张票。']);
 rewrite('c4s09','许持续寄信，云岚却以为他已经不再写。哪一处最先解释这种信息断裂？',[o('c4s09',0,'外部签收单的秦署名'),r('c4s09',0,0,'内册索引缺口'),r('c4s04',2,0,'云岚没收到对应日期的信'),o('c4s09',1,'秦说伯父不许交')],['信已由秦签收，断在交给云岚之前','外部签收与未收到日期相接，秦又承认不交；内册的缺口掩住的是已经进宅的通信。'],['许只留了底稿，实际上从未寄出那些信','独立外部签收单显示信已到秦手里，不只是许自己保存的底稿。'],['云岚收过信，只是没有把回信交给门房','她缺收的日期与秦签收和不交的说明相合，不能据她未回信倒推已经收信。']);
 rewrite('c4s15','若有人怀疑这封信是近日才放进旧库，哪组来源最直接检验这个假说？',[r('c4s15',0,0,'旧入库号与历次清点'),r('c4s15',2,0,'曹婶见过两版交付'),r('c4s15',1,0,'信的实际内容')],['当年入库号、历次清点记录、同号交付见证','三项跨过保存期间，能查出是否近日插入；信写得像父亲或内容对自己不利，都不是保存年代证明。'],['沈砚熟悉的字迹、信里提到的亲人和道歉','这些可辅助作者判断，却不能直接证明文件何时进入库中。'],['信中承认假日期、眼前异本和后来人的评价','内容相合可支持所述事情，仍不独自回答何时入库的问题。']);
 rewrite('c4s18','要找严鹤生本人核投递经过，哪条已经得到回覆的联系链可以继续走？',[r('c4s17',0,-1,'原投递簿的地址'),o('c4s17',2,'公所回覆周泊川'),r('c3s18',1,0,'先前发出的关联查询')],['邵家投递簿→护运公所→现名周泊川的住址','原簿核当年经手与中转处，公所对先前查询回覆改名关联和住址，尚待本人确认。'],['邵家枪柜清单→码头值班员→许慕远的住址','这条联系属于当前家宅命案，并未把许接到十八年前严的投递身份。'],['陆家重装孔→素秋的院籍→冯观澜的车行','这几项解释前案身份替换，不能取代原簿给出的送件姓名与公所地址。']);
 rewrite('c5s02','这次认尸最先出现的矛盾落在哪两个来源之间？',[r('c5s02',0,1,'仆人认出的只有衣物'),r('c5s02',1,0,'妻子说明婚戒习惯'),r('c5s02',2,0,'面容不可可靠辨认')],['衣物身份牌指向周，贴身婚戒却不见，脸又无法核','这使以衣物定人的判断出现缺口，要找更多人身依据；缺戒本身仍有其他可能。'],['客栈记录指向外来者，仆人却认得周的衣服','这时还没取得客栈与外来者材料，不能把后来的可能当成眼前矛盾。'],['周的旧医舍登记，与妻子记得的婚期不合','当前既无这份医舍登记，也无婚期冲突；已出现的是衣物与贴身习惯的差异。']);
 rewrite('c5s05','包裹为何更像被人压沉，而非自己从岸上滑落？',[o('c5s05',0,'成对镇纸少一块'),r('c5s05',2,0,'包裹压着所缺镇纸'),r('c5s05',2,1,'重物包裹和拉绳痕')],['缺失的镇纸压在包上，又有对应拉绳痕','三件组合支持有人用重物和绳安排沉藏；仅潮湿或沉到水底不足以区分意外。'],['包裹进水后变重，所有东西都沉到了池底','水可使物变重，却解释不了桌上特定缺失镇纸为何作为压物与包裹在一起。'],['差役打捞时滑了一跤，包裹此前也可能同样跌落','差役今日滑倒与包裹原来怎样入水不同，不能解释镇纸和拉绳的原状。']);
 rewrite('c5s06','票与客栈登记接上后，下一位最能把“戴魁相关物件”推进到人身核验的对象是谁？',[r('c5s06',1,0,'客栈名字及缺失路段'),o('c5s06',3,'旧雇主明日可来'),r('c5s02',0,1,'仆人只认周的衣服')],['约来认识戴魁的旧雇主，与原登记特征对照','他能提供不同于票与衣物的人身认识，再和既有材料交叉比较。'],['再请周宅仆人确认那套外衣的主人','仆人已经只确认衣物，重复此项仍不能说明遗体是谁。'],['请售票人确认票号对应的班次和路线','这能查旅程段，却未必能辨认使用票的人，更不能单靠票确定棺中身份。']);
 rewrite('c5s09','周自称过去叫严鹤生。哪组新材料能检验这段改名关系，而非只重复他的话？',[o('c4s17',2,'先前身份关联回覆'),r('c5s09',0,-1,'今日两个身份核验分别记'),o('c5s09',1,'公所任务存根到达')],['公所任务存根、连续履历、先前回覆的关联记录','这些有不同保存来路，可接上旧名与现在的人；本人陈述仍与它们互核。'],['戴魁的车票、外来衣物、客栈入住名','它们用于查另一名死者，不能证明周的旧任务和化名经历。'],['周家身份牌、遗体所穿外衣、库房外锁','这些形成假死现场的表象或藏身条件，不说明十八年前的旧名。']);
 rewrite('c5s11','要区分“只是搬账箱”与“撤守后有人纵火烧账”，哪一组能接到实际执行？',[r('c5s11',0,-1,'含混命令与付款链'),r('c5s11',1,0,'亲见引火物进账房'),r('c5s11',1,1,'邻房火灾记录核方向')],['同号付款领款、引火物入账房目击、邻房火向记录','付款接指令与执行人，目击接引火物进入地点，火灾记录再核从何处蔓延，超出了单纯搬物。'],['命令里“清账”两个字、严当时的担心、后来流传的火灾','这些可能让人怀疑，却没有把含混用词接到带引火物进账房的实际执行。'],['林照已被拘押、家属未转走、账箱后来不见','这说明人员处境和结果，仍不能单独区分搬箱后意外起火与组织焚毁。']);
 rewrite('c5s12','把沈砚刚讲的记忆与旧记录对齐，哪种先后没有冲突？',[r('c5s12',0,-1,'沈砚对八岁水患的有限记忆'),r('c5s12',1,-1,'转移簿、拘押登记与火灾日期'),r('c5s12',0,0,'妻子请求留照')],['先水患救出孩子，后林照被拘，随后账房起火','转移簿早于拘押，火灾落在拘押期间；沈砚记得的是更早的水患救援，救助者身份还没有核定。'],['先账房起火，林照救出孩子，随后被带走拘押','火灾发生时林照已在押，而沈砚的水患转移记录更早；不能把救援挪进火里。'],['先林照被拘，再发生水患救援，最后账房起火','转移簿的日期在拘押登记之前，不能将水患救援移到拘押以后。']);
 rewrite('c5s13','戴这一次被派来，哪条已经核到的联系最贴近当次行动？',[o('c5s13',0,'当次送件与混杂近期款'),r('c5s13',0,1,'当次催行条与领款'),r('c5s11',0,-1,'旧案命令编号')],['当次催行条、戴的签收领款、贺铎属下的送件','三项指向同一次出行；韩旧款与近期混款要另查用途，不能自动替代。'],['十八年前撤守命令、韩代理付款、同一批旧印章','它们能接旧案焚毁行动，但没有直接指定戴这一次来访。'],['韩最近的全部付款、周的新回信、失踪的婚戒','最近付款用途混杂，回信与戒指又是当下现场材料，三者尚未组成当次催行指令。']);
 rewrite('c5s18','五案材料能追问韩的烧账指使，关键连接来自哪一组，而非只因每份都有旧商会名字？',[r('c5s11',0,-1,'命令与付款传递'),r('c5s11',1,0,'执行者进入账房'),r('c5s16',0,0,'多方材料核验'),r('c5s18',0,1,'协查和移交回执')],['命令副件的传递号、代理付款同号领款、引火物执行见证','这组将人、指令、钱和具体行动接合，可以向被移交者逐项追问。'],['顾家的抵押编号、钱家的存根、陆家的保证封面','这组接出档案和利益关系，是调查入口，但本身不显示烧账怎样被指使和执行。'],['父亲的自述、温的旧名字、韩到场后的态度','这些涉及责任解释和身份，也无法代替指令与实际执行间的独立连接。']);
 rewrite('c6s02','从黄灯室到公共廊下，首访查过的结构允许成年人走哪条连续通路？',[r('c6s02',1,-1,'事前平面与二十余步距离'),r('c6s02',0,-1,'副件、预约与记录')],['从普通房门出去，沿二十余步的走廊到公共处','门是可走通路，窗有固定铁栅，屏风后为实墙与洗手架，递口只容信封。'],['穿过屏风后空处，再由高窗到公共廊下','屏风后不通外部，高窗也有固定栅，两个不能通人的位置接不成路线。'],['从门旁递口出去，绕外院再进公共处','递口只有信封宽，外院确实存在，却不能补出成年人穿递口的第一步。']);
 rewrite('c6s04','“叫声时温在我身边”先把哪一段排清，又留下哪一段未覆盖？',[r('c6s03',2,0,'何巡先获求救'),r('c6s04',0,0,'共同廊下区间'),r('c6s04',1,0,'插闩前接近')],['叫声时的廊下在场已见；递求救前的接触仍要查','求救纸已说受伤，且比敲门叫声早；廊下见证没有向前覆盖那一段。'],['递求救前温已在廊下；叫声后他可能再进室','现有共同目击只圈到后来廊下时间，没有证明求救以前；先查更早而非倒排。'],['两段都被廊下见证覆盖，只剩高窗路线待查','求救先于叫声，真实见证不能覆盖其尚未开始的时段；高窗还受事前结构限制。']);
 rewrite('c6s06','把插闩的手、破门留下的断舌和倒架声接起来，哪种房内经过与它们相合？',[r('c6s06',1,-2,'宋醒来后摸到内闩'),r('c6s06',0,-1,'应门时抓住洗手架'),r('c6s03',1,1,'破门后的闩与架'),r('c6s02',1,-1,'首访的实际通路')],['伤人者先从房门离开，宋随后插闩；倒架声出自她起身应门','宋自己推闩、破门后断舌仍咬在门框，解释门后来为何锁住；她应门时扶架跌倒，解释较晚的响声，不需要新增逃路。'],['房门始终没有上闩，是倒架顶门；沈砚把阻力当成了门锁','洗手架确实倒了，但门框里仍卡着断闩舌，宋也记得亲手推闩。顶门说解释不了这两条独立事实。'],['伤人者插闩后留到重响，趁她倒下从屏风后的通路离开','屏风后为实墙，高窗又有固定栅；首访结构没有这条逃路，且宋明确记得插闩是自己的动作。']);
 rewrite('c6s08','五案副本都还在，偏偏少了转乙六。它更适合被用来做哪件事？',[r('c6s08',0,-1,'逐件清点失物'),r('c6s02',0,-1,'转乙六载旧转移安排'),r('c6s08',2,0,'旧路线作废')],['知道韩的旧转移安排，尝试在交接中取得控制','失去的是行程副件，不是旧案证据；它对应接人机会，但已作废会使这次用途受阻。'],['删去父亲异本，让旧案无法再查签收日期','父亲与其余旧案副本都在，原件还分处保存，拿转乙六不能删除这些来源。'],['取回林照拘押记录，隐去温从前的姓名','身份材料不是失物，温的旧名此前已完成公开核验。']);
 rewrite('c6s11','接收员的新见证，最需要温补充解释哪一项持件经过？',[r('c6s11',0,-1,'温亲自递转乙六'),r('c6s09',1,-1,'温当面对沈砚的否认'),r('c6s08',0,-1,'事前登记的失物号码')],['温称离室时没拿副件，后来却亲手递来同号件','当面递交使纸件来源成为新的查问对象；还要核它是否失窃原副件、何时取得，不能仅凭同号把先前否认判成假话。'],['宋说原件分处保存，却仍有纸出现在窗口','窗口纸标着交接副件号，不是她所说分处保存的五案原件，两句话可以并存。'],['当班人说旧件不能交人，却仍收下了纸件','拒绝交人和扣留纸件用于核验是两个动作，收件不等于照旧路线放人。']);
 rewrite('c6s13','旧副件没能接走韩，探视凭条也已收回。哪件实际物品解释温后来怎样越过内门？',[r('c6s09',2,0,'凭条回收与外窗边界'),r('c6s11',0,-1,'旧件在窗口被拒'),r('c6s13',2,-2,'后勤员说明夺钥匙'),r('c6s13',2,-1,'守卫到场所见')],['被夺走、原本能越区开内门的后勤钥匙','后勤员亲见被打夺匙，守卫又见钥匙与控制现场，接起旧件受阻后的另一条进入方式。'],['尚未到期的临时问诊凭条','凭条已经回收，外侧投递许可不能进内区，不能解释这次越门。'],['转乙六上原有的路线和接收印','窗口双人已经拒绝交人并扣件，温这次在内门使用的是另一件实物。']);
 rewrite('c6s16','将三件实物接回各案行动链，哪一组对应才吻合你亲自核过的出处？',[r('c1s16',0,-1,'犬舍旧鞋'),o('c4s09',0,'秦的外部收信签押'),r('c6s12',0,-1,'转乙六的实体拼合')],['旧鞋→陶的追踪准备；截信签押→秦的通信控制；转乙六→温的接人尝试','三件分别有不同来路和行为人；跨案关联不抹掉各自实际机制。'],['旧鞋→秦的通信控制；截信签押→温的接人尝试；转乙六→陶的追踪准备','这些人都可能接触纸物，但三个物件的实际取得现场与用途没有这样交叉。'],['旧鞋→温的接人尝试；截信签押→陶的追踪准备；转乙六→秦的通信控制','这种配法依据最后嫌疑倒换前案物件，和犬舍、邵家签收、黄灯桌的独立来源冲突。']);
 rewrite('c6s18','复查者要同时看“同号保证书的内容差异”和“沈怀舟后来留下的异本”，应去核哪两条原件来路？',[r('c3s15',2,-1,'M3两处同号版本'),r('c4s15',0,0,'M4入库与清点'),r('c4s18',1,0,'原信继续留存'),r('c6s18',1,0,'各处原件最终位置')],['陆家与邵家各存的保证书版本；邵行旧库的异本寄存号','前者显示内容差异，后者接父亲交付和保存；两条来源承担不同问题，均可循原处回查。'],['钱庄的灯心付款回执；保护处已作废的转乙六','这两份都真有来路，却属于新近抵押与当次接人，不能回答十八年前文书差异。'],['顾家犬舍的旧鞋清单；周宅沉水包里的车票','这两份用于追踪对象与当下身份，不能补保证书内容和父亲异本保管。']);
 rewrite('c5s02','在眼前三种辨认依据中，哪一项与物件所指的周身份形成了需要解释的反差？',[r('c5s02',0,1,'仆人只认衣物'),r('c5s02',1,0,'妻子说明婚戒习惯'),r('c5s02',2,0,'面容不可可靠辨认')],['周平日不摘婚戒，眼前死者手上却没有','这与长期习惯不合；仍可能有失落等解释，所以要找更多身体依据，不能只让衣服决定名字。'],['外衣与身份牌都被认作周的物品','这两项方向一致，本身没有形成反差；问题在物件是否一直随本人。'],['仆人认得衣物，却说没看清死者的脸','这说明他的辨认能力有限，却未给出与周不合的身体特征；缺戒才是妻子提出的具体反差。']);
 nodes.find(n=>n.sceneId==='c4s05').phaseIndex=1;
 // These five passages are character decisions, not inference puzzles. They
